using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 5%: 249.95 -> 249 off
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // 50.00 enters the +1 band
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)] // 10%
    [InlineData(LoyaltyTier.Green, 19_999, 18_800)]  // 6%: 1199.94 -> 1199 off
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 200.00 enters the +3 band
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10%
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // capped at 10
    [InlineData(LoyaltyTier.Platinum, 19_999, 18_000)] // 10%: 1999.9 -> 1999 off
    [InlineData(LoyaltyTier.Green, 99, 95)]          // 4.95 -> 4 off, rounded down
    [InlineData(LoyaltyTier.Green, 0, 0)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier tier, int subtotalCents, int expectedPayableCents)
    {
        Assert.Equal(expectedPayableCents, new CalculatePayableTotal().For(subtotalCents, tier));
    }
}
E
